import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.CWdVbaJB.js";const u=JSON.parse('{"title":"Data Model","description":"","frontmatter":{"title":"Data Model"},"headers":[],"relativePath":"concepts/data-model.md","filePath":"concepts/data-model.md"}'),n={name:"concepts/data-model.md"};function s(r,e,i,c,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h1><p>SHAVIRA&#39;s data model is built around four core objects: traces, spans, events, and cost records.</p><h2 id="core-objects" tabindex="-1">Core Objects <a class="header-anchor" href="#core-objects" aria-label="Permalink to &quot;Core Objects&quot;">​</a></h2><h3 id="trace" tabindex="-1">Trace <a class="header-anchor" href="#trace" aria-label="Permalink to &quot;Trace&quot;">​</a></h3><p>A trace represents an end-to-end unit of work — typically a single LLM request, agent run, or multi-step workflow. Each trace has:</p><ul><li><strong>traceId</strong> — unique identifier</li><li><strong>name</strong> — descriptive label (e.g., <code>main-chat-flow</code>, <code>incident-summary</code>)</li><li><strong>eventType</strong> — what happened (<code>trace.start</code>, <code>span.end</code>, <code>finding.upsert</code>, <code>cost.record</code>)</li><li><strong>status</strong> — current state</li><li><strong>metadata</strong> — provider, model, environment, service name, instance ID</li></ul><h3 id="span" tabindex="-1">Span <a class="header-anchor" href="#span" aria-label="Permalink to &quot;Span&quot;">​</a></h3><p>A span is a timed sub-step within a trace. Spans are nested to form a tree:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>trace: main-chat-flow</span></span>
<span class="line"><span>├── span: settings-fetch (120ms)</span></span>
<span class="line"><span>├── span: model-call (2.3s)</span></span>
<span class="line"><span>│   └── span: tool-execution (800ms)</span></span>
<span class="line"><span>└── span: response-format (50ms)</span></span></code></pre></div><p>Each span records start/end timestamps, enabling latency analysis at every level.</p><h3 id="event" tabindex="-1">Event <a class="header-anchor" href="#event" aria-label="Permalink to &quot;Event&quot;">​</a></h3><p>An event is a point-in-time occurrence within a trace. Unlike spans, events have no duration — they record that something happened at a specific moment.</p><h3 id="cost-record" tabindex="-1">Cost Record <a class="header-anchor" href="#cost-record" aria-label="Permalink to &quot;Cost Record&quot;">​</a></h3><p>Cost records track the financial cost of LLM usage per trace. Costs are resolved in priority order:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Source</th><th>Reliability</th></tr></thead><tbody><tr><td><strong>Verified</strong></td><td>Provider usage response + model pricing table</td><td>Highest</td></tr><tr><td><strong>Estimated</strong></td><td>Token count from prompt/output text + pricing</td><td>High</td></tr><tr><td><strong>Reported</strong></td><td>Application-provided cost value</td><td>Medium</td></tr><tr><td><strong>Unknown</strong></td><td>Insufficient information</td><td>Lowest</td></tr></tbody></table><h2 id="runtime-identity" tabindex="-1">Runtime Identity <a class="header-anchor" href="#runtime-identity" aria-label="Permalink to &quot;Runtime Identity&quot;">​</a></h2><p>Every trace should carry three identity fields for reliable multi-service observability:</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th><th>Examples</th></tr></thead><tbody><tr><td><code>service_name</code></td><td>Logical service name</td><td><code>ai-chatbot</code>, <code>incident-agent</code></td></tr><tr><td><code>environment</code></td><td>Deployment context</td><td><code>local</code>, <code>staging</code>, <code>prod</code></td></tr><tr><td><code>instance_id</code></td><td>Unique instance</td><td>hostname+PID, container ID</td></tr></tbody></table><h2 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming Conventions&quot;">​</a></h2><p>Use consistent, descriptive names:</p><table tabindex="0"><thead><tr><th>Good</th><th>Avoid</th></tr></thead><tbody><tr><td><code>main-chat-flow</code></td><td><code>test1</code></td></tr><tr><td><code>incident-summary</code></td><td><code>my-trace</code></td></tr><tr><td><code>settings_fetch</code></td><td><code>span_1</code></td></tr><tr><td><code>assistant_run</code></td><td><code>foo</code></td></tr></tbody></table><h2 id="database-schema" tabindex="-1">Database Schema <a class="header-anchor" href="#database-schema" aria-label="Permalink to &quot;Database Schema&quot;">​</a></h2><p>SHAVIRA uses PostgreSQL with the following key tables:</p><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th></tr></thead><tbody><tr><td><code>users</code></td><td>User accounts</td></tr><tr><td><code>workspaces</code></td><td>Workspace isolation</td></tr><tr><td><code>engagements</code></td><td>Engagement sessions</td></tr><tr><td><code>traces</code></td><td>Trace records</td></tr><tr><td><code>ingest_events</code></td><td>Raw ingested events</td></tr><tr><td><code>findings</code></td><td>Security findings</td></tr><tr><td><code>finding_comments</code></td><td>Finding discussion threads</td></tr><tr><td><code>detections</code></td><td>Detection rule definitions</td></tr><tr><td><code>detection_rule_versions</code></td><td>Rule version history</td></tr><tr><td><code>model_endpoints</code></td><td>Registered model endpoints</td></tr><tr><td><code>agents</code></td><td>AI agent definitions</td></tr><tr><td><code>cost_ledger</code></td><td>Cost attribution records</td></tr><tr><td><code>api_keys</code></td><td>API key hashes</td></tr><tr><td><code>audit_log</code></td><td>Audit trail</td></tr></tbody></table><h3 id="workspace-scoping" tabindex="-1">Workspace Scoping <a class="header-anchor" href="#workspace-scoping" aria-label="Permalink to &quot;Workspace Scoping&quot;">​</a></h3><p>Every data table includes a <code>workspace_id</code> column. All queries are scoped by workspace, ensuring hard data isolation between tenants.</p><h3 id="session-and-user-tracking" tabindex="-1">Session and User Tracking <a class="header-anchor" href="#session-and-user-tracking" aria-label="Permalink to &quot;Session and User Tracking&quot;">​</a></h3><p>The <code>ingest_events</code> table includes:</p><ul><li><code>session_id</code> — groups multi-turn conversations</li><li><code>end_user_id</code> — tracks external users</li></ul><p>Compound indexes on <code>(workspace_id, session_id)</code> and <code>(workspace_id, end_user_id)</code> enable efficient aggregation.</p><h3 id="otel-columns" tabindex="-1">OTel Columns <a class="header-anchor" href="#otel-columns" aria-label="Permalink to &quot;OTel Columns&quot;">​</a></h3><p>For OpenTelemetry-ingested spans:</p><ul><li><code>otel_trace_id</code> — original OTel trace ID</li><li><code>otel_span_id</code> — original OTel span ID</li></ul><p>These enable correlation back to the original OTel trace context.</p>`,34)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
